import {describe, it, expect, vi} from 'vitest';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  describe('execute', () => {
    it('rejects input missing a required property with a ToolResponse and never calls the executor', async () => {
      const registry = new ToolRegistry();
      const execute = vi.fn();

      registry.register({
        name: 'test-tool',
        description: 'A test tool',
        inputSchema: {
          type: 'object',
          properties: {
            location: {type: 'string'}
          },
          required: ['location']
        }
      }, execute);

      const response = await registry.execute('test-tool', {});

      expect(execute).not.toHaveBeenCalled();
      expect(response.result).toContain('required');
      expect(response.result).toContain('location');
    });
  });
});
